def _redact_text(value: str) -> str:
    redacted = value
    for index, pattern in enumerate(_SECRET_TEXT_PATTERNS):
        if index in {0, 1}:
            redacted = pattern.sub(r"\1[REDACTED]", redacted)
        elif index == 2:
            redacted = pattern.sub("[REDACTED]", redacted)
        else:
            redacted = pattern.sub(r"\1[REDACTED]@", redacted)
    return redacted


