def _table(counter: Counter, top: Optional[int] = None) -> List[str]:
    items = counter.most_common()
    if top is not None:
        items = items[:top]
    if not items:
        return ["    (none observed)"]
    width = max(len(str(name)) for name, _ in items)
    return ["    %-*s  %d" % (width, name, count) for name, count in items]


